const BreadcrumbWithRdfaMetadata = () => {
  const rdfaMetadata = {
    ol: {
      vocab: 'http://schema.org/',
      typeof: 'BreadcrumbList',
    },
    li: {
      property: 'itemListElement',
      typeof: 'ListItem',
    },
    a: {
      property: 'item',
