const WithRefAndCustomHandlers = (args) => {
  const argTypes = args as unknown as StorybookArguments
  const INITIAL_FILES = null
  const [files, setFiles] = useState<FileList | null>(INITIAL_FILES)
  const fileInputRef = useRef<FileInputRef>(null)

  const handleClearFiles = (): void => {
    fileInputRef.current?.clearFiles()
    setFiles(INITIAL_FILES)
  }

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>): void => {
    argTypes.onChange(e)
    setFiles(e.target?.files)
  }

  const fileList = []
  if (files) {
    for (let i = 0; i < files?.length; i++) {
      fileList.push(<li key={`file_${i}`}>{files?.[Number(i)].name}</li>)
    }
  }

  return (
    <>
      <FormGroup>
        <Label htmlFor="file-input-async">
          Input implements custom handlers
        </Label>
        <FileInput
          id="file-input-async"
          name="file-input-async"
          multiple
          onChange={handleChange}
          onDrop={argTypes.onDrop}
          ref={fileInputRef}
        />
      </FormGroup>

      <button type="button" onClick={handleClearFiles}>
        Clear files
      </button>

      <p>{files?.length || 0} files added:</p>
      <ul>{fileList}</ul>
    </>
  )
};

